CREATE TRIGGER order_number_immutable BEFORE UPDATE OF order_number ON orders WHEN OLD.order_number IS NOT NULL AND NEW.order_number IS NOT OLD.order_number BEGIN SELECT RAISE(ABORT,'订单编号不可修改'); END;
